import numpy as np, torch, model
d=torch.tensor(np.load('contrast_c2_blocks.1_k10.npy')); net=model.load()
xi=torch.tensor(np.load('sim_xi.npy'))[:2048]; c=torch.tensor(np.load('sim_c.npy'))[:2048]
def dec(off=None,thr=0.,lo=8,hi=11):
    x=xi.clone(); ss=[]
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        with torch.no_grad(): v,A=net.velocity(x,t,c,("blocks.1",),count=False)
        s=A["blocks.1"]@d-2.0834; ss.append(s)
        if off is not None and lo<=k<hi:
            v=v+(s>thr).float().unsqueeze(1)*off
        x=x-v/20
    return x,torch.stack(ss)
a0,ss=dec()
lab=ss[:11].mean(0)>0; print('label share',lab.float().mean().item())
d00=torch.cdist(a0,a0); d00.fill_diagonal_(9); print('atyp0',(d00.min(1).values>0.15).float().mean().item())
for lo,hi in [(8,11),(4,8),(0,4)]:
  for mag in [5,10,20]:
    for ang in [0,90,180,270]:
        off=-mag*torch.tensor([np.cos(np.radians(ang)),np.sin(np.radians(ang))],dtype=torch.float32)
        a1,_=dec(off,0.,lo,hi)
        mv=(a1-a0).norm(dim=1); nn=torch.cdist(a1,a0).min(1).values
        print(lo,hi,mag,ang,'labmv %.3f unlabmv %.3f atyp %.3f'%((mv[lab]>0.3).float().mean(),(mv[~lab]>0.3).float().mean(),(nn>0.15).float().mean()))

