import numpy as np, torch, model
from scipy.spatial import cKDTree
net=model.load()
xi=np.load('s_xi.npy'); c=np.load('s_c.npy'); S=np.load('s_S.npy'); bad=np.load('s_bad.npy')
a0=S[20]; N=len(c); src='blocks.2'; tree=cKDTree(a0[~bad])
det=np.load('det_10_14.npy'); w=torch.tensor(det[:-1]); b=float(det[-1])
others=[i for i in range(16) if i not in [4,5,6,14]]
B0={i:np.asarray(model.in_basin(i,a0)).astype(bool) for i in others}
def badf(a):
    r=np.zeros(len(a),bool)
    for i in [4,5,6,14]: r|=np.asarray(model.in_basin(i,a)).astype(bool)
    return r
def run(d,lo=10,hi=14):
    x=torch.tensor(xi); cc=torch.tensor(c)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v,A=net.velocity(x,t,cc,(src,),count=False)
            if lo<=k<hi:
                f=(A[src]@w+b)>0
                v=v+f[:,None].float()*torch.tensor(d,dtype=torch.float32)
            x=x-v/20
    return x.numpy()
for d in [(0.5,5),(1,6),(0,6),(-1,6),(-2,8),(-3,8),(-4,6),(1.5,8),(-1,4)]:
    a=run(d); nb=badf(a)
    rises={i:round(np.asarray(model.in_basin(i,a)).mean()-B0[i].mean(),4) for i in others}
    tot_other=np.zeros(N,bool)
    for i in others: tot_other|=np.asarray(model.in_basin(i,a)).astype(bool)
    o0=np.zeros(N,bool)
    for i in others: o0|=B0[i]
    print(d,'bad',round(nb.mean(),4),'other union rise',round(tot_other.mean()-o0.mean(),4),'r12',rises[12],'r3',rises[3],'r11',rises[11],'off',round((tree.query(a)[0]>0.35).mean()-(0),4))
